code:
.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--gap);
}

.nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

a {
  color: var(--accent);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

/* Visually hidden but still readable by screen readers */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

ul > li:first-child {
  font-weight: bold;
  list-style: none;
}

.title::after {
  content: "";
  display: block;
  width: 3rem;
  height: 3px;
  background: currentColor;
}
